const today=new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Jakarta'});let session,data,editing=null,groups=[],admin=false,loadSerial=0,importRows=[],importReview=null,editingDocument=false,requestKey=null,paymentDocument=null,paymentKey=null,transferEditing=null,transferKey=null;
function status(message,error=false){$('status').textContent=message;$('status').classList.toggle('error',error);}
function login(){const random=()=>Array.from(crypto.getRandomValues(new Uint8Array(32)),x=>x.toString(16).padStart(2,'0')).join('');return(async()=>{const verifier=random(),state=random();sessionStorage.setItem('ygGoogleRequest',JSON.stringify({verifier,state,created:Date.now(),target:'kups-finance.html'}));const hash=new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(verifier)));const challenge=btoa(String.fromCharCode(...hash)).replace(/=/g,'').replace(/\+/g,'-').replace(/\//g,'_');location.assign(base+'/auth/kups?'+new URLSearchParams({state,challenge}));})();}
function signedOut(){evidenceDialog.close();clearEvidencePreview();closeCategoryDetails();++loadSerial;++balanceSerial;++reportSerial;balanceSnapshot=null;entireReportData=null;$('balance-preview').replaceChildren();session=null;data=null;groups=[];$('app').hidden=true;$('login-panel').hidden=false;$('logout').hidden=true;$('user-name').textContent='';for(const id of ['transactions','recent','history','member-list','report-table','kpis','chart','report-summary','report-reconciliation','group-caption','report-group','report-title','group','documents','account-summary','outstanding-summary','report-accounts','report-outstanding','closing-reconciliation','category-breakdown','report-categories'])$(id).replaceChildren();form.reset();$('setup-form').reset();$('member-form').reset();$('reconciliation-form').reset();$('transaction-dialog').close();$('import-dialog').close();importRows=[];importReview=null;$('import-preview').replaceChildren();for(const id of ['payment-dialog','transfer-dialog','accounts-dialog'])$(id).close();$('payment-form').reset();$('transfer-form').reset();$('accounts-form').reset();}
async function api(path,options={}){if(!session?.token)throw Error('Silakan masuk dengan Google.');const headers={Authorization:'Bearer '+session.token,...options.headers};if(options.body&&typeof options.body!=='object'||options.json!==undefined)headers['Content-Type']='application/json';const r=await fetch(base+'/api/kups'+path,{...options,headers,...(options.json!==undefined?{body:JSON.stringify(options.json)}:{}),signal:AbortSignal.timeout(20000)});if(r.status===401){localStorage.removeItem(key);signedOut();throw Error('Sesi berakhir. Masuk kembali.');}if(options.binary){if(!r.ok)throw Error((await r.json()).error||'Bukti tidak tersedia.');return r.blob();}const b=await r.json();if(!r.ok)throw Error(b.error||'Permintaan belum berhasil.');return b;}
