 try{const result=await api('/balances?'+new URLSearchParams({group:$('group').value,date,...(editing?{exclude:editing.id}:{})}));if(seq!==balanceSerial||!session)return;balanceSnapshot=result;renderBalancePreview();}
 catch(e){if(seq===balanceSerial)box.textContent='Saldo belum tersedia: '+e.message;}
