function transferReport(transfers=data.transfers||[]){const rows=transfers.filter(t=>!t.deleted_at);return rows.length?'<h3>Transfer internal · tidak masuk total pemasukan/pengeluaran</h3><div class="table-wrap"><table><thead><tr><th>Tanggal</th><th>Dari → ke</th><th>Uraian</th><th>Nominal</th></tr></thead><tbody>'+rows.map(t=>'<tr><td>'+esc(t.date)+'</td><td>'+accountName(t.from_account)+' → '+accountName(t.to_account)+'</td><td>'+esc(t.description)+'</td><td>'+fmt(t.amount)+'</td></tr>').join('')+'</tbody></table></div>':'';}
async function loadHistory(){try{const rows=await api('/history'+query());const labels={create:'Tambah transaksi',edit:'Edit transaksi',trash:'Pindahkan ke Sampah',restore:'Pulihkan transaksi',setup:'Tetapkan saldo awal',close:'Tutup bulan',reopen:'Buka kembali bulan',member:'Ubah akses anggota',import:'Impor pembukuan',evidence:'Unggah bukti',document_create:'Catat transaksi/tagihan',document_edit:'Edit tagihan',document_trash:'Hapus tagihan',document_restore:'Pulihkan tagihan',payment:'Catat pembayaran tagihan',transfer_create:'Transfer kas/bank',transfer_edit:'Edit transfer',transfer_trash:'Hapus transfer',transfer_restore:'Pulihkan transfer',accounts:'Petakan saldo awal akun'};$('history').innerHTML=rows.length?rows.map(r=>'<div class="history-row"><strong>'+esc(labels[r.action]||r.action)+'</strong><p>'+esc(r.actor)+' · '+new Date(r.created_at).toLocaleString('id-ID')+'</p><details><summary>Rincian perubahan</summary><pre>'+esc(JSON.stringify(JSON.parse(r.snapshot),null,2))+'</pre></details></div>').join(''):'<p class="empty">Belum ada perubahan.</p>';}catch(e){status(e.message,true);}}
