document.addEventListener('click',async event=>{const el=event.target.closest('button');if(!el)return;const d=el.dataset;if(d.categoryKind){openCategoryDetails(el);return;}if(d.view){selectView(d.view);return;}if(d.close){$(d.close).close();return;}if(d.add){openTransaction(d.add);return;}if('transfer' in d){openTransfer();return;}if(el.id==='accounts-open'){$('accounts-form').reset();for(const a of data.accounts||[])if(a.id!=='unassigned')$('accounts-form').elements[a.id].value=a.initial??'';$('accounts-caption').textContent='Tanggal awal '+data.group.start_date+' · Total saldo awal buku '+fmt(data.group.opening_amount);$('accounts-status').textContent='';$('accounts-dialog').showModal();return;}if(d.member){$('member-form').elements.email.value=d.member;$('member-form').elements.role.value=d.role;$('member-form').elements.disabled.value=d.disabled;return;}if(d.docPay||d.docEdit||d.docTrash||d.docRestore||d.docEvidence){const doc=(data.documents||[]).find(t=>t.id===(d.docPay||d.docEdit||d.docTrash||d.docRestore||d.docEvidence));if(!doc)return;try{if(d.docPay)openPayment(doc);if(d.docEdit)openTransaction(doc.kind,doc,true);if(d.docTrash||d.docRestore){const reason=d.docTrash?prompt('Alasan penghapusan tagihan:'):'';if(d.docTrash&&!reason)return;await api('/documents/'+doc.id+'/'+(d.docTrash?'trash':'restore')+query(),{method:'POST',json:{version:doc.version,reason}});await refresh();}if(d.docEvidence){await previewEvidence(doc.evidence_id,'bukti-tagihan-'+doc.id);}}catch(e){status(e.message,true);}return;}if(d.transferEdit||d.transferTrash||d.transferRestore||d.transferEvidence){const t=(data.transfers||[]).find(t=>t.id===(d.transferEdit||d.transferTrash||d.transferRestore||d.transferEvidence));if(!t)return;try{if(d.transferEdit)openTransfer(t);if(d.transferTrash||d.transferRestore){const reason=d.transferTrash?prompt('Alasan penghapusan transfer:'):'';if(d.transferTrash&&!reason)return;await api('/transfers/'+t.id+'/'+(d.transferTrash?'trash':'restore')+query(),{method:'POST',json:{version:t.version,reason}});await refresh();}if(d.transferEvidence){await previewEvidence(t.evidence_id,'bukti-transfer-'+t.id);}}catch(e){status(e.message,true);}return;}const id=d.edit||d.trash||d.restore||d.evidence;if(!id)return;const t=data.rows.find(t=>t.id===id);if(!t)return;try{if(d.edit)openTransaction(t.kind,t);if(d.trash){const reason=prompt('Alasan penghapusan (transaksi dapat dipulihkan):');if(!reason)return;await api('/transactions/'+id+'/trash'+query(),{method:'POST',json:{version:t.version,reason}});await refresh();}if(d.restore){await api('/transactions/'+id+'/restore'+query(),{method:'POST',json:{version:t.version}});await refresh();}if(d.evidence){await previewEvidence(t.evidence_id,'bukti-'+id);}}catch(e){status(e.message,true);}});
$('finance-login').addEventListener('click',()=>login().catch(e=>status(e.message,true)));$('logout').addEventListener('click',async()=>{try{await fetch(base+'/api/webgis/logout',{method:'POST',headers:{Authorization:'Bearer '+session.token},signal:AbortSignal.timeout(10000)});}catch{}localStorage.removeItem(key);signedOut();status('Sesi keuangan di perangkat ini telah diakhiri.');});window.addEventListener('storage',e=>{if(e.key===key)signedOut();});
